package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    # Check for SWITCH type conditional (multi-branch structure)
    cond.type == 2  # ConditionalStatement.ConditionType.SWITCH

    # Check if this is the top-level switch (not an else branch)
    cond.is_top == true

    # Check if there's no default case - either no else_statement or else_statement is not marked as default
    not has_default_case(cond)

    # Check if switch has multiple explicit branches (indicating enumerated conditions without catch-all)
    count_branches(cond) > 1

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in multi-condition expression - Switch or case statements should have a default case to handle unanticipated inputs. (CWE-478)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    # Check for IF type conditional with else_if chain pattern
    cond.type == 1  # ConditionalStatement.ConditionType.IF
    cond.is_top == true

    # Detect if-elif chains without final else
    has_elif_chain_without_else(cond)

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in multi-condition expression - If-elif chains should have a final else clause to handle unanticipated inputs. (CWE-478)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check for Hash objects (dictionaries/maps) used for configuration mapping
    # that may lack default/fallback handling

    walk(parent, [_, node])
    node.ir_type == "Hash"

    # Check if this hash is used in a context suggesting conditional-like mapping
    # by looking for environment/region/instance type keys
    hash_has_conditional_keys(node)

    # Check if hash lacks a default/wildcard/catch-all key
    not hash_has_default_key(node)

    # Ensure hash has multiple keys (not just a single mapping)
    count_hash_keys(node) > 1

    result := {
        "type": "sec_no_default_switch",
        "element": node,
        "path": parent.path,
        "description": "Missing default case in multi-condition expression - Configuration mapping should include a default or fallback case for unhandled keys. (CWE-478)"
    }
}

# Helper: Check if conditional statement has a default case
has_default_case(cond) {
    cond.else_statement != null
    cond.else_statement.is_default == true
} else {
    # Recursive check through else_if chain
    cond.else_statement != null
    has_default_case(cond.else_statement)
}

# Helper: Count total branches in a conditional structure
count_branches(cond) = n {
    n := count_branches_recursive(cond, 0)
}

count_branches_recursive(cond, acc) = n {
    cond.else_statement != null
    new_acc := acc + 2  # current branch + else branch
    n := count_branches_recursive(cond.else_statement, new_acc)
} else {
    cond.else_statement == null
    n := acc + 1
}

# Helper: Detect if-elif chains without final else
has_elif_chain_without_else(cond) {
    # Has at least one else_if (chained condition)
    cond.else_statement != null
    cond.else_statement.type == 1  # IF type (elif)
    cond.else_statement.else_statement == null
} else {
    # Or recursively check deeper chains
    cond.else_statement != null
    cond.else_statement.type == 1
    has_elif_chain_without_else(cond.else_statement)
}

# Helper: Check if hash has keys suggesting conditional configuration
hash_has_conditional_keys(hash) {
    some key
    hash.value[key]
    key.ir_type == "String"
    matches_conditional_pattern(key.value)
}

# Helper: Check for environment/region/type patterns in keys
matches_conditional_pattern(str) {
    patterns := {"dev", "prod", "staging", "test", "development", "production", 
                 "east", "west", "north", "south", "central",
                 "small", "medium", "large", "xl", "xlarge",
                 "enabled", "disabled", "true", "false",
                 "v1", "v2", "v3", "1", "2", "3"}
    lower := lower(str)
    patterns[_] == lower
} else {
    # Check for common conditional prefixes/suffixes
    regex.match("(?i)^(env|environment|region|zone|tier|size|type|mode|version)[_-]?", str)
}

# Helper: Check if hash has a default/wildcard/catch-all key
hash_has_default_key(hash) {
    some key
    hash.value[key]
    key.ir_type == "String"
    is_default_key(key.value)
}

is_default_key(str) {
    lower := lower(str)
    default_keys := {"default", "else", "other", "catchall", "fallback", "*", "_", ""}
    default_keys[_] == lower
}

# Helper: Count non-default keys in hash
count_hash_keys(hash) = n {
    n := count({key |
        some key
        hash.value[key]
        key.ir_type == "String"
        not is_default_key(key.value)
    })
}

iterations.nl_error_summary:
 ## Summary

**Intent:** This rule detects missing default cases in three patterns—`switch` statements, `if-elif` chains, and configuration hashmaps—to flag potential CWE-478 (Missing Default Case in Multiple Condition Expression) vulnerabilities.

**Error:** The OPA compiler fails because `lower` is declared as a local variable (`lower := lower(str)`) inside the `else` bodies of functions `matches_conditional_pattern` and `is_default_key`, but Rego requires that variables assigned with `:=` in one rule branch must appear in **all** branches of that function—or move to a higher scope.

**Fix:** Restructure both helper functions to either (1) move the `lower` assignment outside the `else` block so it applies to all branches, or (2) restructure to avoid conditional variable assignment. For example:

```rego
matches_conditional_pattern(str) {
    lower := lower(str)
    patterns := {...}
    patterns[_] == lower
} else {
    lower := lower(str)  # required: declare in both branches
    regex.match("...", str)
}
```

Or better, lift `lower` out entirely by restructuring the logic or using `lower(str)` inline where needed.

